function init(){const obs=new MutationObserver(()=>{installAdminButtons();installBranchButtons()});obs.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:["hidden","open","lang","dir"]});installAdminButtons();installBranchButtons()}
